object-composition.pseudocode:
class Engine:  # 구성 객체 인터페이스
    def run(self): raise NotImplementedError

class Car:
    def __init__(self, engine):
        self.engine = engine  # has-a: 구성 객체 보관

    def set_engine(self, engine):
        self.engine = engine  # 런타임 교체 (동적 결합)

    def start(self):
        self.engine.run()  # 기능 위임 (블랙박스 재사용)

car = Car(GasEngine())
car.start()
car.set_engine(ElectricEngine())  # 상속 없이 행위 변경
car.start()

