object-tracking.pseudocode:
def sort_step(tracks, dets, iou_th, max_age):
    for t in tracks:
        t.predict()  # 칼만 필터로 현재 위치 예측
    cost = [[1 - iou(t.box, d) for d in dets]
            for t in tracks]
    pairs = hungarian(cost)  # 최소 비용 할당
    used_t, used_d = set(), set()
    for ti, di in pairs:
        if 1 - cost[ti][di] >= iou_th:
            tracks[ti].update(dets[di])  # 관측으로 보정
            tracks[ti].missed = 0
            used_t.add(ti)
            used_d.add(di)
    for i, t in enumerate(tracks):
        if i not in used_t:
            t.missed += 1  # 가림·이탈로 미검출
    for j, d in enumerate(dets):
        if j not in used_d:
            tracks.append(Track(d, new_id()))
    return [t for t in tracks if t.missed <= max_age]

