observer-pattern.pseudocode:
class Subject:
    def __init__(self):
        self.observers = []
        self.state = None

    def attach(self, o):  # 동적 구독
        self.observers.append(o)

    def detach(self, o):  # 구독 해지
        self.observers.remove(o)

    def set_state(self, s):
        self.state = s
        self.notify()  # 상태 변경 → 자동 통지

    def notify(self):
        for o in list(self.observers):
            o.update(self.state)  # 인터페이스로만 호출

class Observer:
    def update(self, state):
        raise NotImplementedError
